        "558": "basic",
        "559": "\n    :root {\n          --my-background-image: url('https://web.sanguosha.com/220/h5_2/res/assets/bigPng/propGet.png');\n    }\n    .sorderContainer {\n        font-size: 13px; /* 默认字体大小，可以根据需要调整 */\n        width: 100%;\n        display: flex; /* 使用Flexbox布局 */\n        align-items: center; /* 垂直居中对齐子元素 */\n        width: 146px;\n        z-index: 10000000000;\n        // color: #f2de9c;\n      user-select: none;\n      text-align: left;\n      transition: height 200ms;\n      position: fixed;\n      transformOrigin = 0 0\n    }\n\n    .sorder-head {\n        display: flex; /* 使用Flexbox */\n        align-items: center; /* 垂直居中 */\n        justify-content: center; /* 水平居中 */\n        font-weight: bolder;\n        width: 10%;\n        height: 25px;\n        text-align: center;\n        color: #f2de9c;\n        margin-left: 3px;\n    }\n\n\n    .sorder-body {\n        pointer-events: auto; /* 子元素可以接收鼠标事件 */\n        height: auto;\n        width: 100%;\n        float: right;\n        display: flex;\n        flex-wrap: wrap; /* 允许内容自动换行 */\n        overflow: hidden;\n        z-index: 1;\n        max-height: 48px; /* 设置一行内容的高度 */\n    }\n\n      /* 使用 ::after 模拟省略号 */\n      .sorder-body.show-ellipsis::after {\n        content: '...';\n        position: absolute;\n        bottom: 0;\n        left: 50%;\n        transform: translateX(-50%);\n        text-align: center;\n        color: #f2de9c;\n        font-weight: bold;\n        height: 20px;\n        background: linear-gradient(to bottom, rgba(255, 255, 255, 0), rgb(0 0 0 / 80%));\n        width: inherit;\n      }\n\n      /* 鼠标悬停时显示完整内容并隐藏省略号 */\n      .sorder-body:hover {\n          max-height: none;\n          overflow: visible;\n      }\n\n      .sorder-body:hover::after {\n          display: none;\n      }\n\n      .sorder-body:not(.paiduiCards) .shoupai:disabled {\n        display: none;\n      }\n      .sorder-body:not(.paiduiCards) .shoupai.G {\n        width: auto;\n      }\n\n      @keyframes fadeInLeftToRight {\n        0% {\n          clip-path: inset(0 100% 0 0);\n          opacity: 0;\n        }\n        100% {\n          clip-path: inset(0 0 0 0);\n          opacity: 1;\n        }\n      }\n\n      @keyframes fadeOutRightToLeft {\n        0% {\n          clip-path: inset(0 0 0 0);\n          opacity: 1;\n        }\n        100% {\n          clip-path: inset(0 100% 0 0);\n          opacity: 0;\n        }\n      }\n      .city{\n        visibility: hidden;\n        transition: opacity 1s ease-in-out, visibility 1s ease-in-out;\n        background-color: rgba(55, 52, 39, 0.7);\n        color: #f2de9c;\n        align-items: center;\n        justify-content: center;\n        border-radius: 5px;\n        text-align: center;\n        flex-direction: column; /* 使flex布局垂直排列 */\n        padding: 5px\n      }\n      hr {\n        width: 100%;\n        margin: 0\n      }\n\n      @keyframes blink {\n          50% {\n              border-color: #f2de9c;\n          }\n      }\n    .show {\n        animation: fadeInLeftToRight 1s forwards, blink 2s infinite;\n        visibility: visible;\n      }\n  .hide {\n    animation: fadeOutRightToLeft 1s forwards;\n    visibility: hidden;\n  }\n .window {\n    width: 1024px;\n    height: 600px;\n    border: 2px solid #333;\n    border-radius: 8px;\n    box-shadow: 0 0 15px rgba(0, 0, 0, 0.5);\n    position: relative;\n    background-color: #f5f5f5;\n    overflow: hidden;\n  }\n\n  .window-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background-color: #23201d;\n    color: white;\n    padding: 5px;\n    cursor: move;\n  }\n\n  .window-header .title {\n    font-weight: bold;\n    padding-left: 10px;\n  }\n\n  .window-header .controls {\n    display: flex;\n    gap: 5px;\n  }\n\n  .window-header .controls button {\n    background: transparent;\n    border: none;\n    color: white;\n    cursor: pointer;\n    padding: 5px;\n  }\n\n  .window-header .controls button:hover {\n    background-color: rgba(255, 255, 255, 0.2);\n  }\n\n  .window-content {\n    width: 100%;\n    height: calc(100% - 40px);\n    border: none;\n  }\n\n  .fullscreen {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100vw;\n    height: 100vh;\n    z-index: 1000;\n  }\n\n  ",
